struct ModelJoint {
    Vec3 rot;  // +0x00: the joint's rotation, Euler angles in degrees (x, y, z)
    Vec3 pos;  // +0x0C: the joint's position in model space
    Vec3 prev_rot;  // +0x18: rot of the frame posed before (model_build_skin)
    Vec3 prev_pos;  // +0x24: pos of the frame posed before
    u8 _unk30[24];
    Vec3 pt_a;  // +0x48: a point in the node's space (the joint's pivot)
    Vec3 pt_a_world;
    Vec3 pt_b;  // +0x60: a second point in the node's space
    Vec3 pt_b_world;  // +0x6C: pt_b in world space, x mirrored
    f32 yaw;  // +0x78: rot.y plus the body's yaw (degrees)
};
