static_assert(offsetof(AnimStream, dma_pending) == 0x3, "AnimStream.dma_pending");
static_assert(offsetof(AnimStream, anim) == 0x4, "AnimStream.anim");
static_assert(offsetof(AnimStream, frame) == 0x6, "AnimStream.frame");
static_assert(offsetof(AnimStream, buf) == 0x8, "AnimStream.buf");
static_assert(offsetof(AnimStream, rom_next) == 0x10, "AnimStream.rom_next");
static_assert(offsetof(AnimStream, bytes_left) == 0x14, "AnimStream.bytes_left");
static_assert(offsetof(AnimStream, scale) == 0x18, "AnimStream.scale");
static_assert(offsetof(AnimStream, _unk58) == 0x58, "AnimStream._unk58");

